function navigateExhibition(id=null,replace=false) {const kind=tab==='series'?'series':'exhibitions';const path=id?`/${kind}/${encodeURIComponent(id)}/edit`:`/${kind}`;history[replace?'replaceState':'pushState']({},'',path);tab=kind;selected=id;render();window.scrollTo({top:0,behavior:'instant'});}
