async function request(url, options = {}) {
 const controller = new AbortController(); const timer = setTimeout(() => controller.abort(), 30000);
 try {
  const response = await fetch(url, {credentials:'same-origin',cache:'no-store',...options,signal:controller.signal});
  const body = await response.json().catch(() => ({}));
  if (!response.ok) throw new Error(response.status === 401 ? 'Время входа истекло. Войдите снова; ваши изменения остаются в этой вкладке.' : body.error || (response.status === 409 ? 'Каталог изменён в другой вкладке. Ваши правки остаются здесь.' : 'Не удалось выполнить действие. Попробуйте снова.'));
  return body;
 } catch (error) { if (error.name === 'AbortError') throw new Error('Сервер не ответил за 30 секунд. Правки остаются здесь; попробуйте ещё раз.'); throw error; }
 finally { clearTimeout(timer); }
}
function uploadImage(file, progress) {
 return new Promise((resolve,reject) => {
  const xhr = new XMLHttpRequest(); xhr.open('POST','/api/studio/media'); xhr.timeout=180000;
  xhr.upload.onprogress = event => progress(event.lengthComputable ? Math.round(event.loaded/event.total*100) : null);
  xhr.onload = () => { let body; try { body=JSON.parse(xhr.responseText); } catch {} if(xhr.status>=200 && xhr.status<300) resolve(body); else reject(new Error(body?.error || 'Не удалось загрузить изображение. Попробуйте ещё раз.')); };
  xhr.onerror=()=>reject(new Error('Соединение прервалось. Проверьте интернет и повторите загрузку.'));
  xhr.ontimeout=()=>reject(new Error('Обработка заняла больше трёх минут. Попробуйте изображение меньшего размера.'));
  const form=new FormData(); form.append('file',file); xhr.send(form);
 });
}
export function initializeContent(id) { if(routeKind()){tab=routeKind();selected=exhibitionRoute();} if (owner && owner !== id) { state = null; dirty = false; } owner = id; if (state) { if (!root.children.length) render(); return; } if (loading) return; const epoch = generation; root.textContent = 'Загружаем каталог…'; loading = request('/api/studio/content').then(data => { if (epoch !== generation) return; state = data; render(); startInbox(); }).catch(error => { root.textContent = error.message; const retry = document.createElement('button'); retry.textContent = 'Повторить'; retry.onclick = () => initializeContent(id); root.append(retry); }).finally(() => { loading = null; }); }
export function resetContent({discard = false} = {}) { if (!discard) return; dismissToast();clearInterval(inboxTimer);inboxTimer=null;inbox={unread:0,requests:[]};document.querySelector('#request-bell').hidden=true;uploadBatch=[];pending=false;document.body.classList.remove('exhibition-management');const welcome=document.querySelector('.studio-heading');if(welcome)welcome.hidden=false; document.title='Studio';document.querySelector('[data-studio-brand]').textContent='Studio';document.querySelector('.header .wordmark').setAttribute('aria-label','Studio');generation++; loading = null; state = null; owner = null; dirty = false; selected = null; modalWorkId = null; modalExhibitionId = null; modalSeriesId = null; archive = false; tab = "works"; for (const key of Object.keys(tabState)) delete tabState[key]; root.replaceChildren(); }
function change() { dirty = true; status(); }
function status() { const node = root.querySelector('#draft-status'); if (node) node.textContent = dirty ? 'Есть несохранённые изменения' : 'Черновик сохранён'; const publish = root.querySelector('#publish-content'); if (publish) publish.disabled = pending; root.querySelectorAll('.print-export').forEach(link => { if (!link.dataset.href) link.dataset.href = link.getAttribute('href') || ''; if (dirty) { link.removeAttribute('href'); link.setAttribute('aria-disabled','true'); link.title='Сначала сохраните черновик'; } else { link.href=link.dataset.href; link.removeAttribute('aria-disabled'); link.removeAttribute('title'); } }); }
