 root.innerHTML=`<div class="catalogue-toolbar"><div><p class="eyebrow">Каталог / Studio</p><h2>${editingExhibition?esc(title(items.find(item=>item.id===selected))):['exhibitions','series'].includes(tab)?(tab==='series'?'Серии':'Выставки'):tab==='about'?'Обо мне':tab==='requests'?'Запросы покупателей':'Работы и истории.'}</h2><span id="draft-status" class="muted"></span></div>${!['exhibitions','series','requests','access'].includes(tab) || editingExhibition?`<div class="toolbar-actions">${button('Сохранить черновик','save','ghost')}${button('Опубликовать','publish','solid')}</div>`:''}</div><nav class="content-tabs" aria-label="Разделы студии">${[['works','Работы'],['series','Серии'],['exhibitions','Выставки'],['about','Обо мне'],['requests','Запросы'],['access','Доступ']].map(([id,label])=>`<button type="button" data-tab="${id}" aria-current="${tab===id?'page':'false'}">${label}</button>`).join('')}</nav><p id="content-message" role="status" aria-live="polite"></p>${['exhibitions','series'].includes(tab)?(editingExhibition?exhibitionEditor:exhibitionList):tab==='about'?aboutEditor():tab==='requests'?inboxMarkup():ordinary}`;
 root.querySelectorAll('[data-edit-exhibition]').forEach(node=>node.onclick=event=>{event.preventDefault();if(!pending)navigateExhibition(node.dataset.editExhibition);});
