 root.querySelectorAll('[data-tab]').forEach(node => node.onclick = () => { if (pending) return; rememberTab(); tab = node.dataset.tab; ({selected = null,archive = false} = tabState[tab] || {}); if(['exhibitions','series'].includes(tab)){navigateExhibition();return;}if(routeKind())history.pushState({},'','/');render(); });
