function displayDate(value) {if(!/^\d{4}-\d{2}-\d{2}$/.test(value || ''))return value || '';return new Intl.DateTimeFormat('en-GB',{day:'numeric',month:'short',year:'numeric',timeZone:'UTC'}).format(new Date(value+'T00:00:00Z'));}
function dropzone(context) {return `<label class="dropzone" data-dropzone="${context}" title="Добавить изображение"><input type="file" accept="image/jpeg,image/png,image/webp,image/avif,image/tiff,.tif,.tiff" ${context==='replace'?'':'multiple'} aria-label="Добавить изображение: нажмите или перетащите файл">${pictureIcon}</label>`;}

